nt-bold">واحد سازمانی</span><select name="department_id" class="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"><option value="">بدون واحد</option><?php $__currentLoopData = $departments; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $d): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($d->id); ?>" <?php echo e($user->department_id===$d->id?'selected':''); ?>><?php echo e($d->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label class="flex items-center gap-3 pt-8"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" <?php echo e(!$user->exists||$user->is_active?'checked':''); ?> class="h-5 w-5 rounded text-emerald-600"><span class="text-sm font-bold">حساب فعال باشد</span></label></div><div class="mt-6 flex justify-end"><button class="rounded-xl bg-emerald-600 px-7 py-3 text-sm font-black text-white hover:bg-emerald-700">ذخیره کاربر</button></div></form><?php $__env->stopSection(); ?>

